1. using System.Diagnostics;
2. using System.IO;
3. using ABLogixGitManager.Models;
4. 
5. namespace ABLogixGitManager.Services;
6. 
7. /// <summary>
8. /// Shells out to l5xgit.exe (and git) to perform commit and pull/restore operations.
9. /// All operations are async, respect cancellation, and stream stdout/stderr back to the
10. /// caller via the <paramref name="onOutput"/> callback.
11. /// </summary>
12. /// <remarks>
13. /// Every public method logs its start, completion, validation failures, and exit codes
14. /// to <see cref="AppLogger"/> so diagnostics are available even when the application
15. /// is run without a terminal.
16. /// </remarks>
17. public class L5xGitCliService
18. {
19.     // -------------------------------------------------------------------------
20.     // Public API
21.     // -------------------------------------------------------------------------
22. 
23.     /// <summary>
24.     /// Validates paths, writes the _L5xGit.yml sidecar, then runs:
25.     ///   l5xgit commit --acd &lt;acdPath&gt;
26.     /// Pipes the commit message to stdin.
27.     /// </summary>
28.     /// <param name="repo">Repository entry containing ACD and git paths.</param>
29.     /// <param name="l5xGitExePath">Full path to l5xgit.exe.</param>
30.     /// <param name="commitMessage">Commit message text supplied by the user.</param>
31.     /// <param name="onOutput">Callback invoked for each line of stdout/stderr.</param>
32.     /// <param name="cancellationToken">Token to cancel the operation mid-flight.</param>
33.     /// <returns>
34.     /// The operation outcome, including <see cref="L5xGitOperationResult.GitRepositoryRequired"/>
35.     /// when the UI must offer repository setup choices.
36.     /// </returns>
37.     public async Task<L5xGitOperationResult> CommitAsync(
38.         RepoEntry repo,
39.         string l5xGitExePath,
40.         string commitMessage,
41.         Action<string> onOutput,
42.         CancellationToken cancellationToken = default)
43.     {
44.         AppLogger.Info($"CommitAsync starting for repo '{repo.Name}', ACD: {repo.AcdFilePath}");
45. 
46.         var validationResult = ValidatePaths(repo, l5xGitExePath, onOutput);
47.         if (validationResult != L5xGitOperationResult.Succeeded)
48.         {
49.             AppLogger.Warn($"CommitAsync aborted — path validation failed for repo '{repo.Name}'.");
50.             return validationResult;
51.         }
52. 
53.         EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);
54. 
55.         // Blank line after the message signals end-of-input to PromptForCommitMessage.
56.         var stdin = commitMessage.Trim() + "\n\n";
57. 
58.         int exitCode = await RunProcessAsync(
59.             exePath: l5xGitExePath,
60.             arguments: ["commit", "--acd", repo.AcdFilePath],
61.             stdinInput: stdin,
62.             onOutput: onOutput,
63.             cancellationToken: cancellationToken);
64. 
65.         AppLogger.Info($"CommitAsync finished for repo '{repo.Name}' — exit code {exitCode}.");
66.         return exitCode == 0
67.             ? L5xGitOperationResult.Succeeded
68.             : L5xGitOperationResult.Failed;
69.     }
70. 
71.     /// <summary>
72.     /// Initializes a git repository in the specified folder.
73.     /// </summary>
74.     public async Task<bool> InitializeGitRepositoryAsync(
75.         string repoPath,
76.         Action<string> onOutput,
77.         CancellationToken cancellationToken = default)
78.     {
79.         AppLogger.Info($"InitializeGitRepositoryAsync starting for '{repoPath}'.");
80. 
81.         if (!Directory.Exists(repoPath))
82.         {
83.             onOutput($"[error] Repository folder not found: {repoPath}");
84.             AppLogger.Warn($"InitializeGitRepositoryAsync failed — folder not found: {repoPath}");
85.             return false;
86.         }
87. 
88.         if (IsGitWorkingTree(repoPath))
89.         {
90.             onOutput($"[info] Git is already initialized at: {repoPath}");
91.             AppLogger.Info($"InitializeGitRepositoryAsync skipped — already initialized: {repoPath}");
92.             return true;
93.         }
94. 
95.         var exitCode = await RunProcessAsync(
96.             exePath: "git",
97.             arguments: ["-C", repoPath, "init"],
98.             stdinInput: null,
99.             onOutput: onOutput,
100.             cancellationToken: cancellationToken);
101. 
102.         if (exitCode != 0)
103.         {
104.             AppLogger.Warn($"InitializeGitRepositoryAsync failed — git init exit code {exitCode} for '{repoPath}'.");
105.             return false;
106.         }
107. 
108.         onOutput($"[done] Initialized Git repository in: {repoPath}");
109.         AppLogger.Info($"InitializeGitRepositoryAsync completed for '{repoPath}'.");
110.         return true;
111.     }
112. 
113.     /// <summary>
114.     /// Clones a repository into the specified destination folder.
115.     /// </summary>
116.     public async Task<bool> CloneRepositoryAsync(
117.         string remoteUrl,
118.         string destinationPath,
119.         Action<string> onOutput,
120.         CancellationToken cancellationToken = default)
121.     {
122.         AppLogger.Info($"CloneRepositoryAsync starting for '{remoteUrl}' -> '{destinationPath}'.");
123. 
124.         if (string.IsNullOrWhiteSpace(remoteUrl))
125.         {
126.             onOutput("[error] Clone URL is required.");
127.             AppLogger.Warn("CloneRepositoryAsync failed — missing remote URL.");
128.             return false;
129.         }
130. 
131.         if (string.IsNullOrWhiteSpace(destinationPath))
132.         {
133.             onOutput("[error] Destination folder is required.");
134.             AppLogger.Warn("CloneRepositoryAsync failed — missing destination path.");
135.             return false;
136.         }
137. 
138.         if (Directory.Exists(destinationPath) && Directory.EnumerateFileSystemEntries(destinationPath).Any())
139.         {
140.             onOutput($"[error] Destination folder is not empty: {destinationPath}");
141.             AppLogger.Warn($"CloneRepositoryAsync failed — destination not empty: {destinationPath}");
142.             return false;
143.         }
144. 
145.         Directory.CreateDirectory(destinationPath);
146. 
147.         var exitCode = await RunProcessAsync(
148.             exePath: "git",
149.             arguments: ["clone", remoteUrl, destinationPath],
150.             stdinInput: null,
151.             onOutput: onOutput,
152.             cancellationToken: cancellationToken);
153. 
154.         if (exitCode != 0)
155.         {
156.             AppLogger.Warn($"CloneRepositoryAsync failed — git clone exit code {exitCode} for '{remoteUrl}'.");
157.             return false;
158.         }
159. 
160.         onOutput($"[done] Cloned repository into: {destinationPath}");
161.         AppLogger.Info($"CloneRepositoryAsync completed for '{remoteUrl}'.");
162.         return true;
163.     }
164. 
165.     /// <summary>
166.     /// Validates paths, runs:
167.     ///   git -C &lt;gitRepoPath&gt; pull
168.     /// and aborts if that step fails, then:
169.     ///   l5xgit restoreacd --acd &lt;acdPath&gt;
170.     /// Pipes "y" to stdin to confirm overwriting the existing ACD file.
171.     /// </summary>
172.     /// <param name="repo">Repository entry containing ACD and git paths.</param>
173.     /// <param name="l5xGitExePath">Full path to l5xgit.exe.</param>
174.     /// <param name="onOutput">Callback invoked for each line of stdout/stderr.</param>
175.     /// <param name="cancellationToken">Token to cancel the operation mid-flight.</param>
176.     public async Task<bool> PullAndRestoreAsync(
177.         RepoEntry repo,
178.         string l5xGitExePath,
179.         Action<string> onOutput,
180.         CancellationToken cancellationToken = default)
181.     {
182.         AppLogger.Info($"PullAndRestoreAsync starting for repo '{repo.Name}', git repo: {repo.GitRepoPath}");
183. 
184.         if (!ValidatePathsForRestore(repo, l5xGitExePath, onOutput))
185.         {
186.             AppLogger.Warn($"PullAndRestoreAsync aborted — path validation failed for repo '{repo.Name}'.");
187.             return false;
188.         }
189. 
190.         onOutput("[git pull] Pulling latest from remote...");
191.         int gitExitCode = await RunProcessAsync(
192.             exePath: "git",
193.             arguments: ["-C", repo.GitRepoPath, "pull"],
194.             stdinInput: null,
195.             onOutput: onOutput,
196.             cancellationToken: cancellationToken);
197. 
198.         if (gitExitCode != 0)
199.         {
200.             var msg = $"git pull failed (exit code {gitExitCode}). Restore cancelled to prevent overwriting with stale content.";
201.             onOutput($"[abort] {msg}");
202.             AppLogger.Error($"PullAndRestoreAsync — {msg} — repo '{repo.Name}'.");
203.             return false;
204.         }
205. 
206.         if (cancellationToken.IsCancellationRequested)
207.         {
208.             AppLogger.Info($"PullAndRestoreAsync cancelled after git pull for repo '{repo.Name}'.");
209.             return false;
210.         }
211. 
212.         EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);
213. 
214.         onOutput("[restoreacd] Imploding and converting to ACD...");
215.         int restoreExitCode = await RunProcessAsync(
216.             exePath: l5xGitExePath,
217.             arguments: ["restoreacd", "--acd", repo.AcdFilePath],
218.             stdinInput: "y\n",
219.             onOutput: onOutput,
220.             cancellationToken: cancellationToken);
221. 
222.         AppLogger.Info($"PullAndRestoreAsync finished for repo '{repo.Name}' — restoreacd exit code {restoreExitCode}.");
223.         return restoreExitCode == 0;
224.     }
225. 
226.     // -------------------------------------------------------------------------
227.     // Private helpers
228.     // -------------------------------------------------------------------------
229. 
230.     /// <summary>
231.     /// Validates l5xgit.exe, the ACD file, and the git repo before a commit.
232.     /// Writes a user-readable error to <paramref name="onOutput"/> on failure.
233.     /// </summary>
234.     private static L5xGitOperationResult ValidatePaths(
235.         RepoEntry repo,
236.         string l5xGitExePath,
237.         Action<string> onOutput)
238.     {
239.         if (string.IsNullOrWhiteSpace(l5xGitExePath))
240.         {
241.             onOutput("[error] l5xgit.exe path is not configured. Open Settings to configure it.");
242.             AppLogger.Warn("ValidatePaths failed — l5xgit.exe path is empty.");
243.             return L5xGitOperationResult.Failed;
244.         }
245. 
246.         if (!File.Exists(l5xGitExePath))
247.         {
248.             onOutput($"[error] l5xgit.exe not found at: {l5xGitExePath}");
249.             AppLogger.Warn($"ValidatePaths failed — l5xgit.exe not found: {l5xGitExePath}");
250.             return L5xGitOperationResult.Failed;
251.         }
252. 
253.         if (!File.Exists(repo.AcdFilePath))
254.         {
255.             onOutput($"[error] ACD file not found: {repo.AcdFilePath}");
256.             AppLogger.Warn($"ValidatePaths failed — ACD not found: {repo.AcdFilePath}");
257.             return L5xGitOperationResult.Failed;
258.         }
259. 
260.         if (!Directory.Exists(repo.GitRepoPath))
261.         {
262.             onOutput($"[error] Git repository path not found: {repo.GitRepoPath}");
263.             AppLogger.Warn($"ValidatePaths failed — git repo not found: {repo.GitRepoPath}");
264.             return L5xGitOperationResult.Failed;
265.         }
266. 
267.         if (!IsGitWorkingTree(repo.GitRepoPath))
268.         {
269.             AppLogger.Warn($"ValidatePaths failed — directory exists but is not a git working tree: {repo.GitRepoPath}");
270.             return L5xGitOperationResult.GitRepositoryRequired;
271.         }
272. 
273.         return L5xGitOperationResult.Succeeded;
274.     }
275. 
276.     /// <summary>
277.     /// Validates l5xgit.exe and the git repo before a restore.
278.     /// The ACD file is not required to exist before restore (it will be created by l5xgit).
279.     /// </summary>
280.     private static bool ValidatePathsForRestore(RepoEntry repo, string l5xGitExePath, Action<string> onOutput)
281.     {
282.         if (string.IsNullOrWhiteSpace(l5xGitExePath))
283.         {
284.             onOutput("[error] l5xgit.exe path is not configured. Open Settings to configure it.");
285.             AppLogger.Warn("ValidatePathsForRestore failed — l5xgit.exe path is empty.");
286.             return false;
287.         }
288. 
289.         if (!File.Exists(l5xGitExePath))
290.         {
291.             onOutput($"[error] l5xgit.exe not found at: {l5xGitExePath}");
292.             AppLogger.Warn($"ValidatePathsForRestore failed — l5xgit.exe not found: {l5xGitExePath}");
293.             return false;
294.         }
295. 
296.         if (!Directory.Exists(repo.GitRepoPath))
297.         {
298.             onOutput($"[error] Git repository path not found: {repo.GitRepoPath}");
299.             AppLogger.Warn($"ValidatePathsForRestore failed — git repo not found: {repo.GitRepoPath}");
300.             return false;
301.         }
302. 
303.         if (!IsGitWorkingTree(repo.GitRepoPath))
304.         {
305.             onOutput($"[error] No Git repository found at '{repo.GitRepoPath}'. Initialize a repo (git init), clone one, or select the correct repository folder.");
306.             AppLogger.Warn($"ValidatePathsForRestore failed — directory exists but is not a git working tree: {repo.GitRepoPath}");
307.             return false;
308.         }
309. 
310.         return true;
311.     }
312. 
313.     /// <summary>
314.     /// Determines whether a directory is a git working tree.
315.     /// </summary>
316.     public static bool IsGitWorkingTree(string repoPath)
317.     {
318.         if (!Directory.Exists(repoPath))
319.             return false;
320. 
321.         var dotGitPath = Path.Combine(repoPath, ".git");
322.         if (Directory.Exists(dotGitPath) || File.Exists(dotGitPath))
323.             return true;
324. 
325.         try
326.         {
327.             var psi = new ProcessStartInfo("git")
328.             {
329.                 UseShellExecute = false,
330.                 CreateNoWindow = true,
331.                 RedirectStandardOutput = true,
332.                 RedirectStandardError = true,
333.             };
334.             psi.ArgumentList.Add("-C");
335.             psi.ArgumentList.Add(repoPath);
336.             psi.ArgumentList.Add("rev-parse");
337.             psi.ArgumentList.Add("--show-toplevel");
338. 
339.             using var process = Process.Start(psi);
340.             if (process is null)
341.                 return false;
342. 
343.             var output = process.StandardOutput.ReadToEnd();
344.             process.WaitForExit();
345. 
346.             if (process.ExitCode != 0 || string.IsNullOrWhiteSpace(output))
347.                 return false;
348. 
349.             var selectedPath = Path.GetFullPath(repoPath)
350.                 .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
351.             var repositoryRoot = Path.GetFullPath(output.Trim())
352.                 .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
353. 
354.             return string.Equals(selectedPath, repositoryRoot, StringComparison.OrdinalIgnoreCase);
355.         }
356.         catch (Exception ex)
357.         {
358.             AppLogger.Error($"IsGitWorkingTree probe failed for '{repoPath}'.", ex);
359.             return false;
360.         }
361.     }
362. 
363.     /// <summary>
364.     /// Writes (or overwrites) the {name}_L5xGit.yml sidecar file next to the ACD.
365.     /// This file tells l5xgit where the git repository lives and enables commit message prompting.
366.     /// </summary>
367.     private static void EnsureL5xGitYml(string acdFilePath, string gitRepoPath)
368.     {
369.         var dir = Path.GetDirectoryName(acdFilePath) ?? string.Empty;
370.         var stem = Path.GetFileNameWithoutExtension(acdFilePath);
371.         var configPath = Path.Combine(dir, $"{stem}_L5xGit.yml");
372. 
373.         // l5xgit expects forward slashes in destination_path.
374.         var normalizedPath = gitRepoPath.Replace('\\', '/');
375. 
376.         var yaml =
377.             $"destination_path: {normalizedPath}\n" +
378.             $"prompt_for_commit_message: true\n";
379. 
380.         File.WriteAllText(configPath, yaml);
381.         AppLogger.Info($"Wrote l5xgit sidecar: {configPath}");
382.     }
383. 
384.     /// <summary>
385.     /// Launches a process using <see cref="ProcessStartInfo.ArgumentList"/> for path-safe
386.     /// argument handling, streams stdout/stderr to <paramref name="onOutput"/>, and returns
387.     /// the process exit code.
388.     /// </summary>
389.     /// <remarks>
390.     /// Using <see cref="ProcessStartInfo.ArgumentList"/> instead of <see cref="ProcessStartInfo.Arguments"/>
391.     /// prevents shell injection and handles paths with spaces without manual quoting.
392.     /// </remarks>
393.     private static async Task<int> RunProcessAsync(
394.         string exePath,
395.         IEnumerable<string> arguments,
396.         string? stdinInput,
397.         Action<string> onOutput,
398.         CancellationToken cancellationToken)
399.     {
400.         var argList = arguments.ToList();
401.         AppLogger.Info($"Launching: {exePath} {string.Join(" ", argList.Select(a => $"\"{a}\""))}");
402. 
403.         var psi = new ProcessStartInfo(exePath)
404.         {
405.             RedirectStandardInput = true,
406.             RedirectStandardOutput = true,
407.             RedirectStandardError = true,
408.             UseShellExecute = false,
409.             CreateNoWindow = true,
410.         };
411. 
412.         foreach (var arg in argList)
413.             psi.ArgumentList.Add(arg);
414. 
415.         using var process = new Process { StartInfo = psi, EnableRaisingEvents = true };
416. 
417.         process.OutputDataReceived += (_, e) =>
418.         {
419.             if (e.Data is not null) onOutput(e.Data);
420.         };
421.         process.ErrorDataReceived += (_, e) =>
422.         {
423.             if (e.Data is not null) onOutput($"[stderr] {e.Data}");
424.         };
425. 
426.         process.Start();
427.         process.BeginOutputReadLine();
428.         process.BeginErrorReadLine();
429. 
430.         if (stdinInput is not null)
431.             await process.StandardInput.WriteAsync(stdinInput);
432. 
433.         process.StandardInput.Close();
434. 
435.         await process.WaitForExitAsync(cancellationToken);
436. 
437.         if (process.ExitCode != 0)
438.         {
439.             onOutput($"[exit code {process.ExitCode}] Process finished with errors.");
440.             AppLogger.Warn($"Process '{exePath}' exited with code {process.ExitCode}.");
441.         }
442.         else
443.         {
444.             onOutput("[done] ✓ Completed successfully.");
445.             AppLogger.Info($"Process '{exePath}' completed successfully.");
446.         }
447. 
448.         return process.ExitCode;
449.     }
450. }
