     /// <summary>
     /// Commits the selected ACD to its git repository using l5xgit.
     /// The commit message is piped to l5xgit stdin.
     /// </summary>
     [RelayCommand(CanExecute = nameof(CanCommit))]
     private async Task CommitAsync()
     {
         if (SelectedRepo is null) return;

         if (!await EnsureGitRepositoryReadyAsync())
             return;

         var repositorySetupRequired = false;

         IsBusy = true;
         OperationStatus = $"Commit started: {SelectedRepo.Name}";
         AppendLog($"--- Commit started: {SelectedRepo.Name} ---");
         AppLogger.Info($"CommitAsync initiated by user for repo '{SelectedRepo.Name}'.");
         _cts = new CancellationTokenSource();

         try
         {
             var result = await _cliService.CommitAsync(
                 repo: SelectedRepo.ToModel(),
                 l5xGitExePath: L5xGitExePath,
                 commitMessage: CommitMessage,
                 onOutput: AppendLog,
                 cancellationToken: _cts.Token);

             if (result == L5xGitOperationResult.Succeeded && !_cts.IsCancellationRequested)
             {
                 CommitMessage = string.Empty;
                 OperationStatus = $"Commit succeeded: {SelectedRepo.Name}";
                 AppendLog($"[done] Commit completed successfully for {SelectedRepo.Name}.");
                 AppLogger.Info($"CommitAsync succeeded for repo '{SelectedRepo?.Name}'.");
             }
             else if (result == L5xGitOperationResult.GitRepositoryRequired)
             {
                 repositorySetupRequired = true;
                 OperationStatus = $"Repository setup required: {SelectedRepo.Name}";
                 AppLogger.Warn($"CommitAsync requires repository setup for '{SelectedRepo.GitRepoPath}'.");
             }
             else
             {
                 OperationStatus = $"Commit failed: {SelectedRepo.Name}";
             }
         }
         catch (OperationCanceledException)
         {
             AppendLog("[cancelled] Operation was cancelled.");
             OperationStatus = $"Commit cancelled: {SelectedRepo.Name}";
             AppLogger.Info($"CommitAsync cancelled for repo '{SelectedRepo?.Name}'.");
         }
         catch (Exception ex)
         {
             AppendLog($"[error] {ex.Message}");
             OperationStatus = $"Commit failed: {SelectedRepo.Name}";
             AppLogger.Error($"CommitAsync failed for repo '{SelectedRepo?.Name}'.", ex);
         }
         finally
         {
             _cts.Dispose();
             _cts = null;
             IsBusy = false;
         }

         if (repositorySetupRequired && await EnsureGitRepositoryReadyAsync(forcePrompt: true))
             await CommitAsync();
     }

