/// <summary>
/// Inspects a single stderr line for known Logix Designer SDK incompatibility signatures
/// and emits an actionable hint when one is detected.
/// </summary>
/// <remarks>
/// The <c>SetRSLinxEdition</c> error occurs when the l5xgit tool was compiled against a
/// different version of the Rockwell Logix Designer SDK than the one registered on the
/// current machine.  Rebuilding l5xgit against the matching SDK version resolves it.
/// </remarks>
private static void EmitLogixSdkCompatibilityHint(string stderrLine, Action<string> onOutput)
{
    if (stderrLine.Contains("SetRSLinxEdition", StringComparison.OrdinalIgnoreCase) ||
        (stderrLine.Contains("OperationFailedException", StringComparison.OrdinalIgnoreCase) &&
         stderrLine.Contains("does not contain a definition for", StringComparison.OrdinalIgnoreCase)))
    {
        onOutput("[hint] Logix Designer SDK version mismatch detected.");
        onOutput("[hint] The l5xgit tool was built against a different version of the Rockwell Logix Designer SDK");
        onOutput("[hint] than the one registered on this machine (Studio 5000 install).");
        onOutput("[hint] Resolution: rebuild l5xgit targeting the SDK version that matches your Studio 5000 installation,");
        onOutput("[hint] or install the Studio 5000 version that matches the SDK used to build l5xgit.");
        AppLogger.Warn($"Logix Designer SDK compatibility error detected in l5xgit stderr: {stderrLine}");
    }
}

