141.             }
142. 
143.             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Missing,
144.                 Message: "Not detected via registry. Install Studio 5000 / Logix Designer from your Rockwell Automation media or FactoryTalk Hub. Organizational IT deployment may be required."));
145.         }
146.         catch (Exception ex)
147.         {
148.             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Failed,
149.                 Message: $"Registry detection failed: {ex.Message}"));
150.         }
