153.     /// <summary>
154.     /// Detects the Logix Designer SDK via Windows registry.
155.     /// The SDK is typically installed alongside Studio 5000.
156.     /// </summary>
157.     public Task<DependencyInfo> CheckLogixDesignerSdkAsync(CancellationToken ct = default)
158.     {
159.         const string name = "Logix Designer SDK";
160.         try
161.         {
162.             var version = DetectRegistryVersion(
163.             [
164.                 @"SOFTWARE\Rockwell Automation\LogixDesignerSDK",
165.                 @"SOFTWARE\WOW6432Node\Rockwell Automation\LogixDesignerSDK",
166.                 @"SOFTWARE\Rockwell Automation\Logix Designer SDK",
