168.             ]);
169. 
170.             if (version is not null)
171.                 return Task.FromResult(new DependencyInfo(name, DependencyStatus.Ready, version));
172. 
173.             var uninstallDetection = DetectInstalledProductFromUninstall(
174.                 "Logix Designer SDK",
175.                 "Studio 5000 SDK");
