192.             }
193. 
194.             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Missing,
195.                 Message: "Not detected via registry or installed-program metadata. The SDK is typically part of Studio 5000. Note: VCS source compile can still succeed when required packages are available from other package sources."));
196.         }
197.         catch (Exception ex)
198.         {
199.             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Failed,
200.                 Message: $"Registry detection failed: {ex.Message}"));
201.         }
