204.     /// <summary>
205.     /// Aggregates Studio 5000 and Logix Designer SDK into a single readiness row.
206.     /// </summary>
207.     public async Task<DependencyInfo> CheckStudioAndLogixSdkAsync(CancellationToken ct = default)
208.     {
209.         const string name = "Studio 5000 & Logix SDK";
210. 
211.         var studioTask = CheckStudio5000Async(ct);
212.         var sdkTask = CheckLogixDesignerSdkAsync(ct);
213.         await Task.WhenAll(studioTask, sdkTask);
214. 
215.         var studio = studioTask.Result;
216.         var sdk = sdkTask.Result;
217. 
218.         if (studio.Status == DependencyStatus.Failed || sdk.Status == DependencyStatus.Failed)
219.         {
220.             return new DependencyInfo(
221.                 name,
222.                 DependencyStatus.Failed,
223.                 Message: $"Studio: {studio.Message ?? studio.Status.ToString()}; SDK: {sdk.Message ?? sdk.Status.ToString()}");
224.         }
225. 
226.         if (studio.Status == DependencyStatus.Ready && sdk.Status == DependencyStatus.Ready)
227.         {
228.             var version = $"Studio={studio.Version ?? "unknown"}, SDK={sdk.Version ?? "unknown"}";
229.             return new DependencyInfo(name, DependencyStatus.Ready, version);
230.         }
231. 
232.         if (studio.Status == DependencyStatus.Missing && sdk.Status == DependencyStatus.Missing)
233.         {
234.             return new DependencyInfo(
235.                 name,
236.                 DependencyStatus.Missing,
237.                 Message: "Both Studio 5000 and Logix SDK are missing. These are required for ACD conversion during commit/restore, but not required to compile Rockwell VCS tools.");
238.         }
239. 
240.         return new DependencyInfo(
241.             name,
242.             DependencyStatus.Incompatible,
243.             Message: $"Partial detection — Studio: {studio.Status}, SDK: {sdk.Status}. Commit/restore needs both; VCS compile can proceed without them.");
244.     }
