246.     /// <summary>
247.     /// Runs all probes concurrently and returns the results in a consistent order.
248.     /// </summary>
249.     public async Task<IReadOnlyList<DependencyInfo>> CheckAllAsync(
250.         string? l5xGitPath,
251.         CancellationToken ct = default)
252.     {
253.         AppLogger.Info("Dependency scan starting.");
254. 
255.         var studioAndSdkTask = CheckStudioAndLogixSdkAsync(ct);
256.         var dotNetTask = CheckDotNetSdkAsync(ct);
257.         var l5xGitTask = CheckL5xGitAsync(l5xGitPath, ct);
258.         var gitTask = CheckGitAsync(ct);
259. 
260.         await Task.WhenAll(studioAndSdkTask, dotNetTask, l5xGitTask, gitTask);
261. 
262.         IReadOnlyList<DependencyInfo> results =
263.         [
264.             studioAndSdkTask.Result,
265.             dotNetTask.Result,
266.             l5xGitTask.Result,
267.             gitTask.Result,
268.         ];
269. 
270.         foreach (var r in results)
271.             AppLogger.Info($"  [{r.Status,-12}] {r.Name} {r.Version ?? string.Empty}");
272. 
273.         var readyCount = results.Count(r => r.Status == DependencyStatus.Ready);
274.         AppLogger.Info($"Dependency scan complete — {readyCount}/{results.Count} ready.");
275. 
276.         return results;
277.     }
