283.     private static string? DetectRegistryVersion(string[] keyPaths)
284.     {
285.         foreach (var path in keyPaths)
286.         {
287.             using var key = Registry.LocalMachine.OpenSubKey(path);
288.             if (key is null) continue;
289. 
290.             var version = key.GetValue("Version") as string
291.                 ?? key.GetValue("InstallVersion") as string;
292. 
293.             return version ?? "(version unknown)";
294.         }
295.         return null;
296.     }
