/// <summary>
/// Forces a git pull + recompile of the already-cloned Rockwell VCS tools, then rescans.
/// Available whenever the local repository clone exists, regardless of whether
/// the current l5xgit.exe is functional. Use this to resolve SDK version mismatches.
/// </summary>
[RelayCommand(CanExecute = nameof(CanRebuildVcsTools))]
private async Task RebuildRockwellVcsToolsAsync()
{
    IsActionBusy = true;
    ActionStatus = "Rebuilding Rockwell VCS tools against local SDK...";
    AppendActionLog("[rebuild] Pulling latest source and rebuilding l5xgit.exe.");
    AppLogger.Info("RebuildRockwellVcsToolsAsync command started.");

    try
    {
        var result = await _installer.InstallAndBuildRockwellVcsToolsAsync(AppendActionLog);
        ActionStatus = result.Message;

        if (result.Success && !string.IsNullOrWhiteSpace(result.L5xGitExePath))
        {
            SaveConfiguredL5xGitPath(result.L5xGitExePath);
            ActionStatus = "Rebuild complete. l5xgit.exe was automatically associated.";
            AppendActionLog($"[settings] Saved l5xgit.exe path: {result.L5xGitExePath}");
        }
        else
        {
            AppendActionLog(result.Success ? $"[done] {result.Message}" : $"[error] {result.Message}");
        }

        AppLogger.Info($"RebuildRockwellVcsToolsAsync command completed. Success={result.Success}. Message={result.Message}");
    }
    catch (Exception ex)
    {
        ActionStatus = $"Rebuild failed: {ex.Message}";
        AppendActionLog($"[error] Rebuild failed: {ex.Message}");
        AppLogger.Error("RebuildRockwellVcsToolsAsync command failed.", ex);
    }
    finally
    {
        IsActionBusy = false;
    }

    await RescanAsync();
}

