/// <summary>
/// Inspects a single stderr line for known Logix Designer SDK incompatibility signatures
/// and emits an actionable hint when one is detected.
/// </summary>
/// <remarks>
/// The <c>SetRSLinxEdition</c> error occurs when the installed Studio 5000 / Logix Designer
/// version is older than V38, which is the minimum required by the VCS tools SDK dependency
/// (<c>RockwellAutomation.LogixDesigner.CSClient v2.*</c>).
/// </remarks>
private static void EmitLogixSdkCompatibilityHint(string stderrLine, Action<string> onOutput)
